import unittest
from config import resolve

class ConfigTests(unittest.TestCase):
    def test_preserves_explicit_values(self):
        self.assertEqual(resolve({'retries': 0, 'enabled': False}), {'retries': 0, 'enabled': False})
    def test_uses_defaults_when_missing(self):
        self.assertEqual(resolve({}), {'retries': 3, 'enabled': True})

if __name__ == '__main__':
    unittest.main()

