import unittest
from decimal import Decimal
from inventory import inventory_total
from models import LineItem

class InventoryTests(unittest.TestCase):
    def test_decimal_total(self):
        items = [LineItem(Decimal('1.25'), 2), LineItem(Decimal('0.10'), 3)]
        self.assertEqual(inventory_total(items), Decimal('2.80'))
    def test_rejects_negative_quantity(self):
        with self.assertRaises(ValueError):
            inventory_total([LineItem(Decimal('1.00'), -1)])

if __name__ == '__main__':
    unittest.main()
